import { chat } from "../llm/client.js";
import { cleanProse, countWordsSafe } from "./score.js";
import type { EffectiveVoice } from "../voice/schema.js";
import { renderVoiceSpec } from "../voice/render.js";

/**
 * Anchors are short passages in the target register that are frozen and
 * re-injected into every later scene. They are generated by the system, so
 * there is no copyrighted text involved, and they do the job that a style
 * description cannot: they fix cadence.
 */
export async function generateAnchors(args: {
  voice: EffectiveVoice;
  premise: string;
  count?: number;
  characters?: Array<{ name: string; role: string; note: string }>;
}): Promise<string[]> {
  const count = args.count ?? 3;
  const cast = (args.characters ?? []).map((c) => `${c.name} (${c.role})`).join(", ");
  const res = await chat({
    messages: [
      {
        role: "system",
        content:
          "You write short prose anchors in a fixed register. Each anchor is a self-contained passage of 150 to 220 words. No headings, no commentary. Separate passages with a line containing only ---.\n\n# VOICE CONTRACT\n" +
          renderVoiceSpec(args.voice),
      },
      {
        role: "user",
        content: [
          `Premise: ${args.premise}`,
          cast ? `Use only these characters, and no other names: ${cast}.` : "",
          ``,
          `Write ${count} passages. Each must be a different kind of scene: one arrival, one conversation, one interval of waiting.`,
          `Each passage must be 150 to 220 words.`,
          `These passages will be reused as fixed cadence anchors, so each must stand alone and must not depend on surrounding plot.`,
          `Do not resolve anything. End each on an object or a fact.`,
        ]
          .filter(Boolean)
          .join("\n"),
      },
    ],
    tier: "flash",
    temperature: 0.95,
    maxTokens: 3000,
    effort: "low",
    tag: "anchors",
  });

  const parts = res.text
    .split(/\n\s*---\s*\n/)
    .map((p) => cleanProse(p))
    .filter((p) => countWordsSafe(p) > 40);

  if (parts.length === 0) {
    throw new Error("Anchor generation returned no usable passages. Retry, or lower reasoning effort.");
  }

  return parts.slice(0, count);
}
